/* Forest Trail: isolated race engine, shared by direct preview and the lesson library. */
const $=s=>document.querySelector(s),canvas=$('#track'),ctx=canvas.getContext('2d');
const forest=new Image(),sprite=new Image();forest.src='assets/forest.png';sprite.src='assets/runner.png';
const runners=[sprite,...['red','violet','blue'].map(color=>{const img=new Image();img.src='assets/runner-kyrgyz-'+color+'.png';return img;})];
let items=[
 ['The path was treacherous after the storm. What does treacherous mean?','dangerous','comfortable','familiar','short'],
 ['Mira was reluctant to speak. She was…','unwilling','excited','unable to hear','confident'],
 ['The instructions were precise. They were…','exact','lengthy','confusing','optional'],
 ['The village had abundant water. It had…','plenty of water','no water','dirty water','expensive water'],
 ['His reply was brief. It was…','short','rude','loud','late'],
 ['The explorer was courageous. She was…','brave','careless','tired','famous']
].map(([prompt,answer,...options])=>({prompt,answer,options}));
const runnerNames=['Turquoise','Red & gold','Violet','Blue & cream'];
let selectedRunner=0;
const picker=document.createElement('div');picker.id='runner-picker';picker.setAttribute('role','group');picker.setAttribute('aria-label','Choose your runner');$('#start').before(picker);
function runnerOrder(){return [selectedRunner,...[0,1,2,3].filter(i=>i!==selectedRunner)];}
function renderPicker(){picker.replaceChildren(...runners.map((img,i)=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(i===selectedRunner));b.dataset.runner=i;const art=document.createElement('span');art.className='runner-portrait';art.style.backgroundImage=`url("${img.getAttribute('src')}")`;b.append(art,document.createTextNode(runnerNames[i]));b.onclick=()=>{selectedRunner=i;renderPicker();draw();};return b;}));document.querySelector('.race-footer > span').textContent='YOU · '+runnerNames[selectedRunner].toUpperCase();}
let s,choices=[],last=0,manual=false;
const rank=()=>1+s.dist.slice(1).filter(d=>d>s.dist[0]).length;
function reset(){s={phase:'ready',index:0,time:6,energy:100,misses:0,correct:0,boost:0,stumble:0,dist:[0,8,-8,18],elapsed:0,review:0,history:[],paused:false};$('#pause').textContent='Pause';$('#pause').disabled=false;$('#callout').textContent='';$('#prompt').textContent='Every word takes you further.';$('#answers').replaceChildren();$('#feedback').textContent='';$('#start').hidden=false;$('#start').textContent='Start the race →';$('#instructions').hidden=false;hud();draw();}
function question(){picker.hidden=true;s.phase='question';s.time=6;s.energy=100;choices=[items[s.index].answer,...items[s.index].options].sort(()=>Math.random()-.5);$('#start').hidden=true;$('#instructions').hidden=true;$('#prompt').textContent=items[s.index].prompt;$('#feedback').textContent='';$('#answers').replaceChildren(...choices.map((a,i)=>{const b=document.createElement('button');const badge=document.createElement('b');badge.textContent=String.fromCharCode(65+i);b.append(badge,document.createTextNode(a));b.onclick=()=>answer(i);return b;}));$('#question-count').textContent=`QUESTION ${s.index+1} / ${items.length}`;}
function answer(i){if(s.phase!=='question'||s.paused)return;const q=items[s.index],good=choices[i]===q.answer;s.phase='review';s.review=2.1;let message;
 if(good){const power=Math.round(20+80*s.time/6);s.correct++;s.misses=0;s.boost=power;s.stumble=0;s.energy=Math.min(100,s.energy+power);message=`Correct! +${power} power`;}
 else{s.misses++;s.boost=0;s.energy=Math.max(0,s.energy-20);if(s.misses>=2){s.stumble=1.8;s.energy=Math.max(0,s.energy-30);s.misses=0;message='Stumble! −30 energy';}else message=i===null?'Time’s up! No boost':'Miss! No boost';}
 s.history.push({prompt:q.prompt,answer:q.answer,correct:good,power:good?s.boost:0,timeout:i===null});$('#callout').textContent=message;$('#feedback').textContent=`${message} · Correct meaning: ${q.answer}`;
 [...$('#answers').children].forEach((b,j)=>{b.disabled=true;if(choices[j]===q.answer)b.classList.add('correct');else if(j===i)b.classList.add('wrong');});hud();}
function finish(){s.phase='done';s.boost=0;$('#callout').textContent=rank()===1?'Forest champion!':'Finish line!';$('#prompt').textContent=`You finished ${['','1st','2nd','3rd','4th'][rank()]}!`;$('#answers').replaceChildren();$('#feedback').textContent=`${s.correct} / ${items.length} correct · ${s.history.reduce((a,h)=>a+h.power,0)} power earned`;$('#start').hidden=false;$('#start').textContent='Race again →';$('#instructions').hidden=false;$('#instructions').textContent='Quick thinking. Stronger strides. Try again to beat your place.';$('#pause').disabled=true;}
function step(dt){if(s.paused||!['question','review'].includes(s.phase))return;s.elapsed+=dt;s.dist[0]+=dt*(s.stumble>0?2:7+s.energy*.035+s.boost*.18);for(let i=1;i<4;i++)s.dist[i]+=dt*[0,12,10.6,9.2][i];s.stumble=Math.max(0,s.stumble-dt);s.boost=Math.max(0,s.boost-dt*12);
 if(s.phase==='question'){s.time=Math.max(0,s.time-dt);s.energy=Math.max(0,s.energy-dt*100/6);if(s.time<=0)answer(null);}else{s.review-=dt;if(s.review<=0){s.index++;$('#callout').textContent='';if(s.index>=items.length)finish();else question();}}hud();}
function hud(){$('#clock').textContent=s.phase==='ready'?'6.0s':s.phase==='done'?'FINISH':`${s.time.toFixed(1)}s`;$('#energy').style.width=`${s.energy}%`;$('#energy').style.background=s.time<2?'#c76441':'';$('#place').textContent=s.phase==='ready'?'FOREST TRAIL':`${['','1st','2nd','3rd','4th'][rank()]} place`;$('#distance').textContent=`${Math.min(s.index+1,items.length)} / ${items.length}`;$('#speed').textContent=s.stumble>0?'STUMBLING':s.boost>0?`BOOST +${Math.ceil(s.boost)}`:`ENERGY ${Math.round(s.energy)}%`;}
function draw(){ctx.clearRect(0,0,1440,550);if(forest.complete&&forest.naturalWidth)ctx.drawImage(forest,0,0,1440,550);else{ctx.fillStyle='#62835e';ctx.fillRect(0,0,1440,550);}const max=Math.max(...s.dist,1),min=Math.min(...s.dist),spread=Math.max(45,max-min+30);const order=[1,2,3,0];
 for(const i of order){const x=s.phase==='ready'?220+i*210:170+(s.dist[i]-min)/spread*950,y=285+i*17,size=i===0?218:185;ctx.fillStyle='#132f2666';ctx.beginPath();ctx.ellipse(x+size/2,y+size*.55,size*.3,9,0,0,7);ctx.fill();
 if(i===0&&s.boost>0){ctx.strokeStyle='#ffe184';ctx.lineWidth=4;ctx.shadowBlur=13;ctx.shadowColor='#ffcf5c';for(let k=0;k<5;k++){ctx.beginPath();ctx.moveTo(x-80-k*9,y+70+k*20);ctx.lineTo(x+75,y+40+k*20);ctx.stroke();}ctx.shadowBlur=0;}
 const frame=s.phase==='ready'||s.phase==='done'?0:Math.floor(s.elapsed*(s.stumble>0&&i===0?4:12)+i*2)%8;
 const runner=runners[runnerOrder()[i]];if(runner.complete&&runner.naturalWidth){const w=runner.naturalWidth/4,h=runner.naturalHeight/2;ctx.save();if(i===0&&s.stumble>0){ctx.translate(x+size/2,y+size/2);ctx.rotate(.28);ctx.translate(-x-size/2,-y-size/2);}ctx.drawImage(runner,(frame%4)*w,Math.floor(frame/4)*h,w,h,x,y-size*.45,size,size);ctx.restore();}
 ctx.font='bold 16px Segoe UI';ctx.textAlign='center';ctx.fillStyle=i===0?'#fff7c9':'#fff';ctx.strokeStyle='#173b2d';ctx.lineWidth=5;const label=i===0?'YOU':['','ASH','FINN','ROSE'][i];ctx.strokeText(label,x+size/2,y-size*.42);ctx.fillText(label,x+size/2,y-size*.42);}
 if(s.paused){ctx.fillStyle='#102b23aa';ctx.fillRect(0,0,1440,550);ctx.fillStyle='#fff4d5';ctx.font='bold 48px Georgia';ctx.textAlign='center';ctx.fillText('Race paused',720,270);}}
$('#start').onclick=()=>{reset();question();};$('#restart').onclick=reset;$('#pause').onclick=()=>{if(!['question','review'].includes(s.phase))return;s.paused=!s.paused;$('#pause').textContent=s.paused?'Resume':'Pause';draw();};$('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!s.paused&&['question','review'].includes(s.phase))$('#pause').click();});
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey)return;const n='1234'.indexOf(e.key);if(n>=0){e.preventDefault();answer(n);}if(e.key.toLowerCase()==='p')$('#pause').click();if(e.key.toLowerCase()==='f')$('#full').click();});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||!Array.isArray(e.data?.vocabularyItems))return;const data=e.data.vocabularyItems;if(data.length>=2&&data.every(q=>typeof q.prompt==='string'&&typeof q.answer==='string'&&Array.isArray(q.options)&&q.options.length&&q.options.every(a=>typeof a==='string'))){items=data;reset();}});
window.render_game_to_text=()=>JSON.stringify({...s,selectedRunner,runnerOrder:runnerOrder(),choices,question:items[Math.min(s.index,items.length-1)].prompt,place:rank(),coordinates:'Canvas 1440x550, origin top-left; runners travel right; distance in race units'});
window.advanceTime=ms=>{manual=true;for(let remaining=ms;remaining>0;remaining-=16.6667)step(Math.min(remaining,16.6667)/1000);draw();};
const resetRace=reset;reset=function(){resetRace();picker.hidden=false;renderPicker();$('#prompt').textContent='Choose your runner';$('#question-count').textContent='YOUR NEXT ADVENTURE';$('#instructions').innerHTML='6 seconds per question. Faster correct answers give more power.<br>Two misses in a row? You stumble and lose energy.';};$('#restart').onclick=()=>reset();
function frame(t){const dt=Math.min((t-last)/1000,.05);last=t;if(!manual)step(dt);draw();requestAnimationFrame(frame);}reset();requestAnimationFrame(frame);
